import random

def generate_random_number() -> int:
    return random.randint(1, 100)

def is_palindrome(text: str) -> bool:
    normalized = ''.join(char.lower() for char in text if char.isalnum())
    return normalized == normalized[::-1]

def mean(numbers):
    if not numbers:
        raise ValueError('numbers must not be empty')
    return sum(numbers) / len(numbers)

def median(numbers):
    if not numbers:
        raise ValueError('numbers must not be empty')
    ordered = sorted(numbers)
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

import re

def slugify(text: str) -> str:
    value = re.sub(r'[^a-z0-9]+', '-', text.lower())
    return value.strip('-')

def parse_bool(value):
    if isinstance(value, bool):
        return value
    normalized = str(value).strip().lower()
    if normalized in {'true', 'yes', '1', 'on'}:
        return True
    if normalized in {'false', 'no', '0', 'off'}:
        return False
    raise ValueError(f'invalid boolean value: {value}')

def unique_in_order(items):
    result = []
    for item in items:
        if item not in result:
            result.append(item)
    return result

def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None

import re

def word_frequencies(text: str) -> dict[str, int]:
    counts: dict[str, int] = {}
    for word in re.findall(r'[A-Za-z0-9]+', text.lower()):
        counts[word] = counts.get(word, 0) + 1
    return counts

class Inventory:
    def __init__(self):
        self._stock = {}

    def add(self, name, amount):
        if amount < 0:
            raise ValueError('amount must be non-negative')
        self._stock[name] = self.stock(name) + amount

    def remove(self, name, amount):
        if amount < 0 or self.stock(name) < amount:
            raise ValueError('insufficient stock')
        self._stock[name] -= amount

    def stock(self, name):
        return self._stock.get(name, 0)
